"""HTTP routes for the profile area.

One function per route. The application object in app.py imports this module
and registers each of them.
"""

from models import User, SupportTicket


def get_profile(session, user_id):
    user = session.get(User, user_id)
    return {"email": user.email, "metadata_json": user.metadata_json}


def list_tickets(session, user_id):
    support_ticket = session.query(SupportTicket).filter(SupportTicket.user_id == user_id).first()
    return {"subject": support_ticket.subject, "notes": support_ticket.notes}

"""Small string helpers. No personal data passes through this module."""


def slugify(value):
    return "-".join(part for part in value.lower().split() if part)


def truncate(value, limit=80):
    if len(value) <= limit:
        return value
    return value[: limit - 3] + "..."


def humanise_bytes(count):
    for unit in ("B", "KB", "MB"):
        if count < 1024:
            return f"{count} {unit}"
        count //= 1024
    return f"{count} GB"
